func siparisDetayText(_ text: String, lang: String) -> String {
    if let exact = siparisDetayLocalTranslations[text]?[lang] { return exact }
    if let english = siparisDetayLocalTranslations[text]?["English"] { return english }
    return t(text, lang: lang)
}


/// Returns a `Locale` best matching the active app language.
/// Used by `DateFormatter`, `NumberFormatter` etc. so chart axis labels,
/// calendar headers and month names render in the user's language.
func studioLocale(_ lang: String) -> Locale {
    switch lang {
    case "Türkçe": return Locale(identifier: "tr")
    case "Deutsch": return Locale(identifier: "de")
    case "Français": return Locale(identifier: "fr")
    case "Italiano": return Locale(identifier: "it")
    case "Español (Spanish)": return Locale(identifier: "es")
    case "Português": return Locale(identifier: "pt")
    case "Русский (Russian)": return Locale(identifier: "ru")
    case "日本語 (Japanese)": return Locale(identifier: "ja")
    case "中文 (Chinese)": return Locale(identifier: "zh")
    case "العربية (Arabic)": return Locale(identifier: "ar")
    case "हिन्दी (Hindi)": return Locale(identifier: "hi")
    default: return Locale(identifier: "en_GB")
    }
}

/// Maps the device's preferred locale to one of the app's 12 supported
/// language names. Used ONCE, on first launch, to pick a sensible default —
/// an explicit user choice in Settings always wins afterwards.
func studioLanguageForDeviceLocale(_ identifier: String? = nil) -> String {
    let raw = (identifier ?? Locale.preferredLanguages.first ?? "en").lowercased()
    let code = raw.split(separator: "-").first.map(String.init) ?? raw
    switch code {
    case "tr": return "Türkçe"
    case "de": return "Deutsch"
    case "fr": return "Français"
    case "it": return "Italiano"
    case "es": return "Español (Spanish)"
    case "pt": return "Português"
    case "ru": return "Русский (Russian)"
    case "ja": return "日本語 (Japanese)"
    case "zh": return "中文 (Chinese)"
    case "ar": return "العربية (Arabic)"
    case "hi": return "हिन्दी (Hindi)"
    default: return "English"
    }
}

/// First-launch default: if the user has never chosen an app language on this
/// device, seed it from the device locale so the app opens in their language.
func seedStudioLanguageFromDeviceIfNeeded() {
    let defaults = UserDefaults.standard
    guard defaults.string(forKey: "seciliDil") == nil else { return }
    defaults.set(studioLanguageForDeviceLocale(), forKey: "seciliDil")
}

func t(_ text: String, lang: String) -> String {
    if let translated = studioFlowFeatureTranslations[text]?[lang] { return translated }
    if let translated = globalDilSozlugu[text]?[lang] { return translated }
    return text
}

func formatFiyat(_ val: Double, ondalik: String) -> String {
    let formatter = NumberFormatter(); formatter.numberStyle = .decimal; formatter.minimumFractionDigits = 2; formatter.maximumFractionDigits = 2; formatter.decimalSeparator = ondalik; formatter.groupingSeparator = ondalik == "," ? "." : ","
    return formatter.string(from: NSNumber(value: val)) ?? String(format: "%.2f", val).replacingOccurrences(of: ".", with: ondalik)
}
